// datetime.date / datetime.datetime stand-ins matching CPython str()/isoformat()
// output as used by PyYAML's represent_date / represent_datetime.

function pad(n, w) {
  let s = String(n);
  while (s.length < w) s = '0' + s;
  return s;
}

export class YamlDate {
  constructor(year, month, day) {
    this.year = year; this.month = month; this.day = day;
  }
  isoformat() {
    return pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2);
  }
}

export class YamlDateTime {
  // tzOffset: minutes east of UTC, or null for naive.
  constructor(year, month, day, hour, minute, second, microsecond, tzOffset) {
    this.year = year; this.month = month; this.day = day;
    this.hour = hour; this.minute = minute; this.second = second;
    this.microsecond = microsecond; this.tzOffset = tzOffset;
  }
  isoformat(sep) {
    let s = pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2)
      + sep + pad(this.hour, 2) + ':' + pad(this.minute, 2) + ':' + pad(this.second, 2);
    if (this.microsecond !== 0) s += '.' + pad(this.microsecond, 6);
    if (this.tzOffset !== null) {
      const off = this.tzOffset;
      const sign = off < 0 ? '-' : '+';
      const a = Math.abs(off);
      s += sign + pad(Math.floor(a / 60), 2) + ':' + pad(a % 60, 2);
    }
    return s;
  }
  // UTC instant in microseconds (only meaningful when tzOffset !== null).
  utcMicros() {
    const days = daysFromCivil(this.year, this.month, this.day);
    return ((days * 24 + this.hour) * 60 + this.minute - this.tzOffset) * 60000000
      + this.second * 1000000 + this.microsecond;
  }
}

// Howard Hinnant's days_from_civil.
function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

// Python equality between two keys of date/datetime type (other types handled
// elsewhere). Returns true/false.
export function timeEquals(a, b) {
  const aDate = a instanceof YamlDate;
  const bDate = b instanceof YamlDate;
  const aDt = a instanceof YamlDateTime;
  const bDt = b instanceof YamlDateTime;
  if (aDate && bDate) {
    return a.year === b.year && a.month === b.month && a.day === b.day;
  }
  if (aDt && bDt) {
    const aAware = a.tzOffset !== null;
    const bAware = b.tzOffset !== null;
    if (aAware && bAware) return a.utcMicros() === b.utcMicros();
    if (aAware !== bAware) return false; // naive == aware is False in Python
    return a.year === b.year && a.month === b.month && a.day === b.day
      && a.hour === b.hour && a.minute === b.minute && a.second === b.second
      && a.microsecond === b.microsecond;
  }
  return false; // date never equals datetime
}

// Python ordering comparison between date/datetime keys.
// Throws a TypeError-like Error when Python would raise TypeError.
export function timeCompare(a, b) {
  const aDate = a instanceof YamlDate;
  const bDate = b instanceof YamlDate;
  const aDt = a instanceof YamlDateTime;
  const bDt = b instanceof YamlDateTime;
  if (aDate && bDate) {
    return cmpNum(a.year, b.year) || cmpNum(a.month, b.month) || cmpNum(a.day, b.day);
  }
  if (aDt && bDt) {
    const aAware = a.tzOffset !== null;
    const bAware = b.tzOffset !== null;
    if (aAware !== bAware) {
      throw new Error("TypeError: can't compare offset-naive and offset-aware datetimes");
    }
    if (aAware) return cmpNum(a.utcMicros(), b.utcMicros());
    return cmpNum(a.year, b.year) || cmpNum(a.month, b.month) || cmpNum(a.day, b.day)
      || cmpNum(a.hour, b.hour) || cmpNum(a.minute, b.minute) || cmpNum(a.second, b.second)
      || cmpNum(a.microsecond, b.microsecond);
  }
  throw new Error("TypeError: can't compare datetime.datetime to datetime.date");
}

function cmpNum(a, b) { return a < b ? -1 : a > b ? 1 : 0; }

