// Python dict semantics for constructed YAML mappings: insertion order,
// Python equality for keys (True == 1 == 1.0), hashability rules,
// and Python sorted() ordering for yaml.dump's represent_mapping.

import { YamlDate, YamlDateTime, timeEquals, timeCompare } from './pytime.mjs';

// A key is "numeric" in Python terms: bool, int (BigInt here), float (number).
function isNumericKey(v) {
  return typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number';
}

// Compare numeric keys exactly; returns true/false for ==.
function numericEquals(a, b) {
  const na = toNumeric(a);
  const nb = toNumeric(b);
  if (na.kind === 'float' || nb.kind === 'float') {
    const fa = toFloat(na);
    const fb = toFloat(nb);
    if (Number.isNaN(fa) || Number.isNaN(fb)) return false;
    if (fa === Infinity || fa === -Infinity || fb === Infinity || fb === -Infinity) {
      return fa === fb;
    }
    // Exact comparison between BigInt and double.
    if (na.kind === 'bigint' && nb.kind === 'bigint') return na.value === nb.value;
    if (na.kind === 'bigint') return bigintEqualsFloat(na.value, fb);
    if (nb.kind === 'bigint') return bigintEqualsFloat(nb.value, fa);
    return fa === fb;
  }
  return na.value === nb.value;
}

function toNumeric(v) {
  if (typeof v === 'boolean') return { kind: 'bigint', value: v ? 1n : 0n };
  if (typeof v === 'bigint') return { kind: 'bigint', value: v };
  return { kind: 'float', value: v };
}

function toFloat(n) {
  return n.kind === 'bigint' ? bigintToFloat(n.value) : n.value;
}

function bigintToFloat(b) {
  // May lose precision for huge ints, only used for Infinity/NaN screening.
  return Number(b);
}

function bigintEqualsFloat(b, f) {
  if (!Number.isInteger(f)) return false;
  if (!Number.isFinite(f)) return false;
  // Safe: integers beyond 2^53 compare via exact BigInt conversion of the
  // double's exact mathematical value.
  return b === BigInt(f);
}

// Python == for YAML scalar keys.
export function pyKeyEquals(a, b) {
  if (isNumericKey(a) && isNumericKey(b)) return numericEquals(a, b);
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if (a === null || b === null) return a === b;
  if ((a instanceof YamlDate || a instanceof YamlDateTime)
      && (b instanceof YamlDate || b instanceof YamlDateTime)) {
    return timeEquals(a, b);
  }
  return false;
}

// Python hashability: lists/dicts are unhashable.
export function pyHashable(v) {
  return !(Array.isArray(v) || v instanceof PyMap);
}

// Ordered map with Python dict semantics.
export class PyMap {
  constructor() {
    this.pairs = []; // [key, value]
  }
  set(key, value) {
    for (const pair of this.pairs) {
      if (pyKeyEquals(pair[0], key)) {
        pair[1] = value;
        return;
      }
    }
    this.pairs.push([key, value]);
  }
  get size() { return this.pairs.length; }
}

// Python '<' between two sort keys. Throws Error('TypeError...') when Python
// would raise TypeError. NaN compares equal to everything (stable in place).
export function pyKeyCompare(a, b) {
  if (typeof a === 'string' && typeof b === 'string') {
    // Compare by code point (Python semantics), not UTF-16 units.
    const ca = Array.from(a);
    const cb = Array.from(b);
    const n = Math.min(ca.length, cb.length);
    for (let i = 0; i < n; i++) {
      const pa = ca[i].codePointAt(0);
      const pb = cb[i].codePointAt(0);
      if (pa !== pb) return pa < pb ? -1 : 1;
    }
    if (ca.length === cb.length) return 0;
    return ca.length < cb.length ? -1 : 1;
  }
  if (isNumericKey(a) && isNumericKey(b)) {
    const na = toNumeric(a);
    const nb = toNumeric(b);
    const fa = toFloat(na);
    const fb = toFloat(nb);
    if (Number.isNaN(fa) || Number.isNaN(fb)) return 0;
    if (na.kind === 'bigint' && nb.kind === 'bigint') {
      return na.value < nb.value ? -1 : na.value > nb.value ? 1 : 0;
    }
    if (na.kind === 'bigint') return bigintCompareFloat(na.value, fb);
    if (nb.kind === 'bigint') return -bigintCompareFloat(nb.value, fa);
    return fa < fb ? -1 : fa > fb ? 1 : 0;
  }
  if ((a instanceof YamlDate || a instanceof YamlDateTime)
      && (b instanceof YamlDate || b instanceof YamlDateTime)) {
    return timeCompare(a, b);
  }
  throw new Error('TypeError: unorderable types');
}

function bigintCompareFloat(b, f) {
  if (Number.isNaN(f)) return 0;
  if (f === Infinity) return -1;
  if (f === -Infinity) return 1;
  if (Number.isInteger(f)) {
    const fb = BigInt(f);
    return b < fb ? -1 : b > fb ? 1 : 0;
  }
  // Non-integral float: compare against floor/ceil.
  const ff = BigInt(Math.floor(f));
  if (b < ff) return -1;
  if (b > ff) return 1;
  return -1; // b == floor(f) < f
}

// PyYAML BaseRepresenter.represent_mapping sorts the item list with Python
// sorted(); on TypeError the original order is kept.
export function pySortPairs(pairs) {
  const copy = pairs.slice();
  try {
    copy.sort((pa, pb) => pyKeyCompare(pa[0], pb[0]));
    return copy;
  } catch (e) {
    if (e instanceof Error && e.message.startsWith('TypeError')) return pairs;
    throw e;
  }
}

