// Minimal argparse emulation for: parser with one required option `--a`
// taking exactly one value. Matches CPython argparse exit codes:
//   0 on success, 2 on any CLI error (message to stderr), 0 for -h/--help.

function prog() {
  const p = process.argv[1] || 'test20.mjs';
  const parts = p.split('/');
  return parts[parts.length - 1];
}

function usage() {
  return 'usage: ' + prog() + ' [-h] --a A';
}

function errorExit(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(prog() + ': error: ' + message + '\n');
  process.exit(2);
}

function looksLikeOption(tok) {
  // argparse: a token starting with a prefix char is treated as an option
  // unless it is a negative number (parser has no number-like options) or it
  // is a single '-'.
  if (tok.length === 0 || tok[0] !== '-') return false;
  if (tok === '-') return false;
  if (isNegativeNumber(tok)) return false;
  return true;
}

function isNegativeNumber(tok) {
  // argparse's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$
  if (tok[0] !== '-') return false;
  const s = tok.slice(1);
  if (s.length === 0) return false;
  if (allDigits(s)) return true;
  // -\d*\.\d+
  const dot = s.indexOf('.');
  if (dot === -1) return false;
  const intPart = s.slice(0, dot);
  const fracPart = s.slice(dot + 1);
  if (fracPart.length === 0) return false;
  if (intPart.length > 0 && !allDigits(intPart)) return false;
  return allDigits(fracPart);
}

function allDigits(s) {
  if (s.length === 0) return false;
  for (const ch of s) {
    if (ch < '0' || ch > '9') return false;
  }
  return true;
}

function printHelp() {
  let out = usage() + '\n\noptions:\n';
  out += '  -h, --help  show this help message and exit\n';
  out += '  --a A\n';
  process.stdout.write(out);
  process.exit(0);
}

// Returns the value of --a, or exits the process like argparse.
export function parseArgs(args) {
  let aValue = null;
  let aSeen = false;
  const extras = [];
  let i = 0;
  let noMoreOptions = false;
  while (i < args.length) {
    const tok = args[i];
    if (!noMoreOptions && tok === '--') {
      noMoreOptions = true;
      i++;
      continue;
    }
    if (!noMoreOptions && tok.startsWith('--')) {
      // Long option, possibly with =value; allow unambiguous abbreviations.
      let name = tok;
      let attached = null;
      const eq = tok.indexOf('=');
      if (eq !== -1) {
        name = tok.slice(0, eq);
        attached = tok.slice(eq + 1);
      }
      const matches = [];
      for (const opt of ['--help', '--a']) {
        if (opt === name) { matches.length = 0; matches.push(opt); break; }
        if (opt.startsWith(name)) matches.push(opt);
      }
      if (matches.length === 1) {
        const opt = matches[0];
        if (opt === '--help') {
          if (attached !== null) errorExit('argument -h/--help: ignored explicit argument ' + squote(attached));
          printHelp();
        }
        // --a
        if (attached !== null) {
          aValue = attached;
          aSeen = true;
        } else {
          const next = i + 1 < args.length ? args[i + 1] : null;
          if (next === null || looksLikeOption(next)) {
            errorExit('argument --a: expected one argument');
          }
          aValue = next;
          aSeen = true;
          i++;
        }
      } else if (matches.length > 1) {
        errorExit('ambiguous option: ' + name + ' could match ' + matches.join(', '));
      } else {
        extras.push(tok);
      }
    } else if (!noMoreOptions && tok.length > 1 && tok[0] === '-' && !isNegativeNumber(tok)) {
      // Short option cluster.
      if (tok === '-h') {
        printHelp();
      }
      extras.push(tok);
    } else {
      extras.push(tok);
    }
    i++;
  }
  if (extras.length > 0) {
    errorExit('unrecognized arguments: ' + extras.join(' '));
  }
  if (!aSeen) {
    errorExit('the following arguments are required: --a');
  }
  return aValue;
}

