// PyYAML SafeLoader implicit resolver (YAML 1.1 flavors), hand-coded
// without regular expressions.

export const TAG_STR = 'tag:yaml.org,2002:str';
export const TAG_NULL = 'tag:yaml.org,2002:null';
export const TAG_BOOL = 'tag:yaml.org,2002:bool';
export const TAG_INT = 'tag:yaml.org,2002:int';
export const TAG_FLOAT = 'tag:yaml.org,2002:float';
export const TAG_TIMESTAMP = 'tag:yaml.org,2002:timestamp';
export const TAG_MERGE = 'tag:yaml.org,2002:merge';
export const TAG_VALUE = 'tag:yaml.org,2002:value';
export const TAG_SEQ = 'tag:yaml.org,2002:seq';
export const TAG_MAP = 'tag:yaml.org,2002:map';

function isDigit(ch) { return ch >= '0' && ch <= '9'; }
function isDigitOrUnderscore(ch) { return isDigit(ch) || ch === '_'; }

function allMatch(s, from, pred) {
  if (from >= s.length) return false; // need at least one char
  for (let i = from; i < s.length; i++) {
    if (!pred(s[i])) return false;
  }
  return true;
}

// null: ~ | null | Null | NULL | (empty)
function matchNull(v) {
  return v === '' || v === '~' || v === 'null' || v === 'Null' || v === 'NULL';
}

const BOOL_VALUES = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

function matchBool(v) {
  return BOOL_VALUES.includes(v);
}

// int:
//   [-+]?0b[0-1_]+
//   [-+]?0[0-7_]+
//   [-+]?(0|[1-9][0-9_]*)
//   [-+]?0x[0-9a-fA-F_]+
//   [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
function matchInt(v) {
  let s = v;
  if (s[0] === '+' || s[0] === '-') s = s.slice(1);
  if (s === '') return false;
  if (s.length > 2 && s[0] === '0' && s[1] === 'b') {
    return allMatch(s, 2, (c) => c === '0' || c === '1' || c === '_');
  }
  if (s.length > 2 && s[0] === '0' && s[1] === 'x') {
    return allMatch(s, 2, (c) => isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F') || c === '_');
  }
  if (s.length > 1 && s[0] === '0'
      && allMatch(s, 1, (c) => (c >= '0' && c <= '7') || c === '_')) {
    return true;
  }
  if (s === '0') return true;
  if (s[0] >= '1' && s[0] <= '9' && allMatch(s, 1, isDigitOrUnderscore)) return true;
  // sexagesimal
  if (s[0] >= '1' && s[0] <= '9' && s.includes(':')) {
    const segs = s.split(':');
    if (segs.length < 2) return false;
    const first = segs[0];
    if (!(first[0] >= '1' && first[0] <= '9')) return false;
    if (!allMatch(first, 1, isDigitOrUnderscore) && first.length > 1) return false;
    for (let k = 1; k < segs.length; k++) {
      const g = segs[k];
      if (g.length === 1) {
        if (!isDigit(g[0])) return false;
      } else if (g.length === 2) {
        if (!(g[0] >= '0' && g[0] <= '5') || !isDigit(g[1])) return false;
      } else {
        return false;
      }
    }
    return true;
  }
  return false;
}

// float:
//   [-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
//   \.[0-9][0-9_]*([eE][-+][0-9]+)?
//   [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
//   [-+]?\.(inf|Inf|INF)
//   \.(nan|NaN|NAN)
function matchFloat(v) {
  if (v === '.nan' || v === '.NaN' || v === '.NAN') return true;
  let s = v;
  if (s[0] === '+' || s[0] === '-') s = s.slice(1);
  if (s === '.inf' || s === '.Inf' || s === '.INF') return true;
  if (s === '') return false;
  // sexagesimal float
  if (s.includes(':')) {
    const dotParts = s.split('.');
    if (dotParts.length !== 2) return false;
    const frac = dotParts[1];
    if (!(frac === '' || allMatch(frac, 0, isDigitOrUnderscore))) return false;
    const segs = dotParts[0].split(':');
    if (segs.length < 2) return false;
    const first = segs[0];
    if (!isDigit(first[0])) return false;
    if (!allMatch(first, 1, isDigitOrUnderscore) && first.length > 1) return false;
    for (let k = 1; k < segs.length; k++) {
      const g = segs[k];
      if (g.length === 1) {
        if (!isDigit(g[0])) return false;
      } else if (g.length === 2) {
        if (!(g[0] >= '0' && g[0] <= '5') || !isDigit(g[1])) return false;
      } else {
        return false;
      }
    }
    return true;
  }
  // leading-dot form: \.[0-9][0-9_]*([eE][-+][0-9]+)?   (no sign!)
  if (v[0] === '.') {
    return matchFloatTail(v.slice(1), true);
  }
  // standard form: [0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
  if (!isDigit(s[0])) return false;
  let i = 1;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (s[i] !== '.') return false;
  i++;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (i === s.length) return true;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] !== '+' && s[i] !== '-') return false;
    i++;
    return allMatch(s, i, isDigit);
  }
  return false;
}

// helper for leading-dot float: digits/underscores then optional exponent.
function matchFloatTail(s, needDigit) {
  if (s === '') return false;
  let i = 0;
  if (!isDigit(s[0])) return false;
  i = 1;
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  if (i === s.length) return true;
  if (s[i] === 'e' || s[i] === 'E') {
    i++;
    if (s[i] !== '+' && s[i] !== '-') return false;
    i++;
    return allMatch(s, i, isDigit);
  }
  return false;
}

// timestamp:
//   [0-9]{4}-[0-9]{2}-[0-9]{2}
//   [0-9]{4}-[0-9]{1,2}-[0-9]{1,2}([Tt]|[ \t]+)[0-9]{1,2}:[0-9]{2}:[0-9]{2}
//     (\.[0-9]*)?([ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?))?
export function matchTimestamp(v) {
  const chars = Array.from(v);
  const n = chars.length;
  function digitAt(i) { return i < n && isDigit(chars[i]); }
  // date part: YYYY-
  if (n < 10) return false;
  for (let i = 0; i < 4; i++) if (!digitAt(i)) return false;
  if (chars[4] !== '-') return false;
  let i = 5;
  let mDigits = 0;
  while (i < n && isDigit(chars[i]) && mDigits < 2) { i++; mDigits++; }
  if (mDigits === 0) return false;
  if (i >= n || chars[i] !== '-') return false;
  i++;
  let dDigits = 0;
  while (i < n && isDigit(chars[i]) && dDigits < 2) { i++; dDigits++; }
  if (dDigits === 0) return false;
  if (i === n) {
    // date-only requires exactly 2-digit month and day
    return mDigits === 2 && dDigits === 2;
  }
  // separator: [Tt] or [ \t]+
  if (chars[i] === 'T' || chars[i] === 't') {
    i++;
  } else if (chars[i] === ' ' || chars[i] === '\t') {
    while (i < n && (chars[i] === ' ' || chars[i] === '\t')) i++;
  } else {
    return false;
  }
  // hour: [0-9][0-9]?
  if (!digitAt(i)) return false;
  i++;
  if (digitAt(i)) i++;
  if (i >= n || chars[i] !== ':') return false;
  i++;
  // minute: [0-9][0-9]
  if (!digitAt(i) || !digitAt(i + 1)) return false;
  i += 2;
  if (i >= n || chars[i] !== ':') return false;
  i++;
  // second: [0-9][0-9]
  if (!digitAt(i) || !digitAt(i + 1)) return false;
  i += 2;
  // fraction: (\.[0-9]*)?
  if (i < n && chars[i] === '.') {
    i++;
    while (i < n && isDigit(chars[i])) i++;
  }
  // timezone: ([ \t]*(Z|[-+][0-9][0-9]?(:[0-9][0-9])?))?
  if (i === n) return true;
  while (i < n && (chars[i] === ' ' || chars[i] === '\t')) i++;
  if (i === n) return true;
  if (chars[i] === 'Z') {
    i++;
    return i === n;
  }
  if (chars[i] === '+' || chars[i] === '-') {
    i++;
    if (!digitAt(i)) return false;
    i++;
    if (digitAt(i)) i++;
    if (i < n && chars[i] === ':') {
      i++;
      if (!digitAt(i) || !digitAt(i + 1)) return false;
      i += 2;
    }
    return i === n;
  }
  return false;
}

// Resolve a plain (implicit) scalar's tag, mirroring PyYAML SafeLoader.
export function resolvePlainScalar(value) {
  if (value === '') return TAG_NULL;
  const first = value[0];
  switch (first) {
    case '~': case 'n': case 'N':
      if (matchNull(value)) return TAG_NULL;
      break;
    case 'y': case 'Y': case 't': case 'T': case 'f': case 'F': case 'o': case 'O':
      if (matchBool(value)) return TAG_BOOL;
      break;
    case '<':
      if (value === '<<') return TAG_MERGE;
      break;
    case '=':
      if (value === '=') return TAG_VALUE;
      break;
    case '-': case '+': case '.':
      if (matchFloat(value)) return TAG_FLOAT;
      if (matchInt(value)) return TAG_INT;
      break;
    default:
      if (isDigit(first)) {
        if (matchTimestamp(value)) return TAG_TIMESTAMP;
        if (matchInt(value)) return TAG_INT;
        if (matchFloat(value)) return TAG_FLOAT;
      }
  }
  return TAG_STR;
}

// PyYAML Resolver.resolve for the two implicit flag combinations.
export function resolveScalar(value, implicit) {
  if (implicit[0]) {
    return resolvePlainScalar(value);
  }
  return TAG_STR;
}

// Exported matchers used by the constructor.
export { matchNull, matchBool, matchInt, matchFloat };

